import re
ATTR_NAME_RE = re.compile(r'[^a-z0-9]+')
def norm(n):
    return ATTR_NAME_RE.sub('_', n.strip().lower()).strip('_')
seen = {}
for n in names:
    k = norm(n)
    seen.setdefault(k, []).append(n)
for k,v in seen.items():
